    61	  test('only name is load-bearing — no name means nothing to render yet', () => {
    62	    expect(map(undefined)).toBeNull();
    63	    expect(map(null)).toBeNull();
    64	    expect(map({ ...FULL, name: undefined })).toBeNull();
    65	    expect(map({ ...FULL, name: '' })).toBeNull();
    66	  });
