    68	  test('an absent price renders empty rather than "NaN" or "undefined"', () => {
    69	    expect(map(FULL, null)?.price).toBe('');
    70	    expect(map(FULL, {})?.price).toBe('');
    71	    expect(map(FULL, { currentPrice: undefined })?.price).toBe('');
    72	  });
    73	
