    80	  test('calls the injected formatter once with the storefront currency', () => {
    81	    const spy = vi.fn(() => '$895.00');
    82	    selectPdpProductInfo(FULL, { currentPrice: 895 }, 'AUD', spy);
    83	    expect(spy).toHaveBeenCalledOnce();
    84	    expect(spy).toHaveBeenCalledWith(895, 'AUD');
    85	  });
