// MUT_MAP: JSON object mapping absolute repo source path -> absolute mutated copy path.
const MUT_MAP: Record<string, string> = process.env.MUT_MAP ? JSON.parse(process.env.MUT_MAP) : {};

const mutateRedirect = {
  name: 'mutate-redirect',
  enforce: 'pre' as const,
  async resolveId(source: string, importer: string | undefined, options: any) {
