     1	import type { Meta, StoryObj } from '@storybook/react-webpack5';
     2	import React from 'react';
     3	import { expect, within } from 'storybook/test';
     4	import { Box } from '@chakra-ui/react';
     5	import { ZimmProductContent } from '.';
     6	
     7	/** The real Shopper Products payload for 8637DS241 (ZimmermannAU, 2026-08-23). */
     8	const REAL_DESCRIPTION = [
     9	  'The Natura Mini Dress in Blue Birds from our Spring 2024 Collection, Natura. ',
    10	  'A long sleeve linen mini dress featuring a deep v-neckline with fitted bodice and full skirt.',
    11	  '<br><ul><li> Linen mini dress</li><li> Long sleeves with fluted cuffs </li>',
    12	  '<li> Crinoline hem </li><li> Invisible zip at centre back</li></ul>',
    13	].join('');
    14	
    15	const meta: Meta<typeof ZimmProductContent> = {
    16	  title: 'Commerce/ZimmProductContent',
    17	  component: ZimmProductContent,
    18	  argTypes: {
    19	    name: { control: 'text' },
    20	    currentPrice: { control: 'text' },
    21	    originalPrice: { control: 'text' },
    22	    description: { control: 'text' },
    23	    headingLevel: { control: 'inline-radio', options: ['h1', 'h2', 'h3'] },
    24	  },
    25	  decorators: [
    26	    // The DS Content frame is 218px wide inside the info column; showing it at any other
    27	    // width makes the wrap behaviour and the 20px rhythm unreadable.
    28	    (Story: React.ComponentType) => (
    29	      <Box width="218px">
    30	        <Story />
    31	      </Box>
    32	    ),
    33	  ],
    34	};
    35	export default meta;
    36	
    37	type Story = StoryObj<typeof ZimmProductContent>;
    38	
    39	export const Default: Story = {
    40	  args: {
    41	    name: 'Natura Mini Dress',
    42	    headingLevel: 'h1',
    43	    currentPrice: '$795.00',
    44	    description: REAL_DESCRIPTION,
    45	  },
    46	};
    47	
    48	export const OnSale: Story = {
    49	  name: 'On sale — Was/Now price treatment (PRC-09)',
    50	  args: {
    51	    name: 'Natura Mini Dress',
    52	    headingLevel: 'h1',
    53	    currentPrice: '$450.00',
    54	    originalPrice: '$795.00',
    55	    description: REAL_DESCRIPTION,
    56	  },
    57	};
    58	
    59	export const WithoutDescription: Story = {
    60	  name: 'Without description — rhythm collapses',
    61	  args: {
    62	    name: 'Natura Mini Dress',
    63	    headingLevel: 'h1',
    64	    currentPrice: '$795.00',
    65	    description: undefined,
    66	  },
    67	  play: async ({ canvasElement }) => {
    68	    const canvas = within(canvasElement);
    69	    const root = canvas.getByTestId('product-content');
    70	
    71	    // The description atom returns null, so the group must be exactly two rows with no
    72	    // trailing gap. A per-child marginBottom would leave 20px hanging under the price.
    73	    await expect(canvas.queryByTestId('product-description')).not.toBeInTheDocument();
    74	    await expect(root.children).toHaveLength(2);
    75	
    76	    // A flex gap applies only between rendered items, so two children means exactly one gap
    77	    // and no trailing space under the price.
    78	    await expect(getComputedStyle(root).rowGap).toBe('20px');
    79	  },
    80	};
    81	
    82	export const RhythmWithDescription: Story = {
    83	  name: 'Rhythm — 20px between every row',
    84	  args: {
    85	    name: 'Natura Mini Dress',
    86	    headingLevel: 'h1',
    87	    currentPrice: '$795.00',
    88	    description: '<p>A long sleeve linen mini dress.</p>',
    89	  },
    90	  play: async ({ canvasElement }) => {
    91	    const root = within(canvasElement).getByTestId('product-content');
    92	    await expect(root.children).toHaveLength(3);
    93	
    94	    // 20px = spacing.l, asserted as a computed value so a change to the token, to the recipe,
    95	    // or to its registration in theme/components/index.ts all surface here rather than only in
    96	    // a visual review. It also pins down that no child can out-specify the container.
    97	    await expect(getComputedStyle(root).rowGap).toBe('20px');
    98	    for (const child of Array.from(root.children)) {
    99	      await expect(getComputedStyle(child).marginTop).toBe('0px');
   100	    }
   101	  },
   102	};
   103	
   104	export const BlankDescription: Story = {
   105	  name: 'Description present but empty — also collapses',
   106	  // Business Manager can save the field as empty markup rather than clearing it, which is not
   107	  // the same input as `undefined` and has to reach the same rendering.
   108	  args: {
   109	    name: 'Natura Mini Dress',
   110	    headingLevel: 'h1',
   111	    currentPrice: '$795.00',
   112	    description: '<p></p>',
   113	  },
   114	  play: async ({ canvasElement }) => {
   115	    const canvas = within(canvasElement);
   116	    await expect(canvas.getByTestId('product-content').children).toHaveLength(2);
   117	    await expect(canvas.queryByTestId('product-description')).not.toBeInTheDocument();
   118	  },
   119	};
   120	
   121	export const WithoutPrice: Story = {
   122	  name: 'Price absent — the price row collapses too',
   123	  // Not a hypothetical: the page's mapper resolves a product with no price data to `''` rather
   124	  // than to a formatted NaN, and that empty string reaches ZimmProductPrice unchanged.
   125	  args: {
   126	    name: 'Natura Mini Dress',
   127	    headingLevel: 'h1',
   128	    currentPrice: '',
   129	    description: '<p>A long sleeve linen mini dress.</p>',
   130	  },
   131	  play: async ({ canvasElement }) => {
   132	    const canvas = within(canvasElement);
   133	    const root = canvas.getByTestId('product-content');
   134	
   135	    // The middle row is the one that disappears here, so this also pins down that the rhythm
   136	    // is a container `gap` and not a per-child margin — a margin on the name would leave the
   137	    // 20px hanging above a price that is no longer there.
   138	    await expect(canvas.queryByTestId('product-price')).not.toBeInTheDocument();
   139	    await expect(canvas.getByTestId('product-name')).toBeInTheDocument();
   140	    await expect(canvas.getByTestId('product-description')).toBeInTheDocument();
   141	    await expect(getComputedStyle(root).rowGap).toBe('20px');
   142	  },
   143	};

