cat > "$SP/scenario/scenario2.test.ts" <<'EOF'
/** Decisive test for finding #7 in the REAL page path: product = the stale standalone variant. */
import { describe, expect, test } from 'vitest';
import { selectVariantScopedPriceData } from '/Users/marcel.a.n.navarro/Dev/zimmermann-pwa/overrides/app/pages/product-detail/variantScopedPrice';

const v = (productId: string, color: string, size: string, price: number, list: number) => ({
  productId,
  variationValues: { color, size },
  price,
  tieredPrices: [
    { quantity: 1, price },
    { quantity: 1, price: list },
  ],
});

const colourX_S = v('M1', 'X', 'S', 100, 200);
const colourX_M = v('M2', 'X', 'M', 100, 200);
const colourY_L = v('Y1', 'Y', 'L', 555, 999);
const ALL = [colourX_S, colourX_M, colourY_L];

const master = { id: 'MASTER-1', type: { master: true }, variants: ALL };

// The product actually fetched when the URL still carries pid=M1: the STANDALONE VARIANT.
// Shape A — SFCC returns variants[] on the variant response (what the #6 comment asserts).
const staleVariantWithVariants = {
  id: 'M1',
  type: { variant: true },
  master: { masterId: 'MASTER-1' },
  variationValues: { color: 'X', size: 'S' },
  price: 100,
  tieredPrices: colourX_S.tieredPrices,
  variants: ALL,
};
// Shape B — variant response WITHOUT variants[] (what the cachedMaster path exists for).
const staleVariantNoVariants = { ...staleVariantWithVariants, variants: undefined };

describe('#7 in the real page path — product is the stale standalone variant (pid=M1), URL colour=Y', () => {
  test('Shape A (variant response INCLUDES variants[]) — which price is produced?', () => {
    const r: any = selectVariantScopedPriceData(staleVariantWithVariants as any, master as any, 'M1', 'Y');
    // eslint-disable-next-line no-console
    console.log('SHAPE-A =>', JSON.stringify(r));
    expect(r).toBeTruthy();
  });

  test('Shape B (variant response OMITS variants[], cached master supplies them)', () => {
    const r: any = selectVariantScopedPriceData(staleVariantNoVariants as any, master as any, 'M1', 'Y');
    // eslint-disable-next-line no-console
    console.log('SHAPE-B =>', JSON.stringify(r));
    expect(r).toBeTruthy();
  });

  test('reference — colour Y priced from the master directly', () => {
    const r: any = selectVariantScopedPriceData(master as any, null, undefined, 'Y');
    // eslint-disable-next-line no-console
    console.log('REFERENCE-Y =>', JSON.stringify(r));
  });

  test('reference — colour X priced from the master directly', () => {
    const r: any = selectVariantScopedPriceData(master as any, null, undefined, 'X');
    // eslint-disable-next-line no-console
    console.log('REFERENCE-X =>', JSON.stringify(r));
  });
});
EOF
npx vitest run --config "$SP/vitest.scenario.config.ts" --reporter=default scenario2 2>&1 | grep -E "SHAPE-|REFERENCE-|Tests "

